#!/usr/bin/env python3
"""Pack original 1.2.5 UI pixels without scaling; retain frame geometry and hashes."""
import argparse,hashlib,json
from pathlib import Path
from PIL import Image
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--source',type=Path,default=Path('/workspace/windows-port/original-textures'));p.add_argument('--mod-source',type=Path,default=Path('/workspace/windows-port/mod-textures'));a=p.parse_args()
game=Path(__file__).resolve().parents[1];assets=game/'assets';sprites=json.loads((a.source/'sprites.json').read_text())['sprites'];textures=json.loads((a.source/'textures.json').read_text());cache={}
selected={'sp_garage':'garages','sp_garage_icons':'garageIcons','sp_garage_lift':'lifts','sp_buttons':'buttons','sp_buttons_tools':'tools','sp_font_pixel':'glyphs','sp_bars':'bars','sp_engine':'engines','sp_coilovers':'suspensions','sp_turbo':'turbos','sp_ecu':'ecus','sp_nos':'nos','sp_airfilter':'intakes','sp_intercooler':'intercoolers','sp_piston':'pistons','sp_muffler':'exhausts'}
mod_sprites=json.loads((a.mod_source/'sprites.json').read_text())['sprites'];mod_textures=json.loads((a.mod_source/'textures.json').read_text())
content={'sp_engine','sp_coilovers','sp_turbo','sp_ecu','sp_nos','sp_airfilter','sp_intercooler','sp_piston','sp_muffler'}
size=2048;pages=[Image.new('RGBA',(size,size))];x=y=rowh=0;groups={};sources={}
for name,group in selected.items():
 source=a.mod_source if name in content else a.source;table=mod_textures if name in content else textures
 s=next(s for s in (mod_sprites if name in content else sprites) if s['name']==name);rows=[]
 for f in s['frames']:
  if f is None:rows.append([-1,0,0,0,0,0,0,0,0]);continue
  file=f['file'];key=str(source/file)
  if key not in cache:
   digest=hashlib.file_digest((source/file).open('rb'),'sha256').hexdigest();expected=next(t['sha256'] for t in table if t['file']==file)
   if digest!=expected:raise ValueError('Original UI atlas digest mismatch: '+file)
   sources[source.name+'/'+file]=digest;cache[key]=Image.open(source/file).convert('RGBA')
  sx,sy,w,h=f['source_rect'];pic=cache[key].crop((sx,sy,sx+w,sy+h))
  if x+w+2>size:x=0;y+=rowh+2;rowh=0
  if y+h+2>size:pages.append(Image.new('RGBA',(size,size)));x=y=rowh=0
  pages[-1].paste(pic,(x+1,y+1));rows.append([1000+len(pages)-1,x+1,y+1,w,h,*f['target_offset'],s['width'],s['height']]);x+=w+2;rowh=max(rowh,h)
 groups[group]=rows
header=['// Original 1.2.5 UI and Unbound item pixels, repacked without scaling; generated by prepare_original_ui.py.','#pragma once','#include "art.hpp"','namespace pcr::original_ui {','using Frame=art::Frame;']
for group,rows in groups.items():
 header.append('inline const Frame '+group+'[] = {');header+=['{'+','.join(map(str,row))+'},' for row in rows];header.append('};')
header+=['inline constexpr int AtlasCount='+str(len(pages))+';','}'];(game/'src/original_ui.hpp').write_text('\n'.join(header)+'\n')
manifest=[]
for i,page in enumerate(pages):
 file=f'original-ui-{i:02d}.png';page.save(assets/file,optimize=True);manifest.append({'file':file,'sha256':hashlib.file_digest((assets/file).open('rb'),'sha256').hexdigest()})
provenance=json.loads((assets/'provenance.json').read_text());provenance['files']=[f for f in provenance['files'] if not f['file'].startswith('original-ui-')]+manifest;provenance['original_ui']={'source':'Original Pixel Car Racer 1.2.5 UI; supplied Unbound item images retained','sprites':selected,'source_atlas_sha256':sources,'packing':'Unscaled source RGBA crop pixels, transparent padding; no original code executed'}
(assets/'provenance.json').write_text(json.dumps(provenance,indent=2)+'\n');(game/'validation/original-ui-source.json').write_text(json.dumps(provenance['original_ui'],indent=2)+'\n')
print('Packed',len(groups),'original UI groups and',sum(map(len,groups.values())),'frames in',len(pages),'atlases')
